import re
import sqlite3

from langchain_core.tools import tool

_DB_PATH = "claims.db"
_CLAIM_RE = re.compile(r"^CLM-\d{8}$")


@tool
def lookup_claim_status(claim_number: str, include_notes: bool = False) -> dict:
    if not claim_number or not _CLAIM_RE.match(claim_number.strip()):
        return {"error": "claim_number must look like CLM-12345678"}
    conn = sqlite3.connect(_DB_PATH)
    conn.row_factory = sqlite3.Row
    row = conn.execute(
        "SELECT claim_number, status, adjuster, reserve_amount, notes FROM claims WHERE claim_number = ?",
        (claim_number.strip(),),
    ).fetchone()
    conn.close()
    if row is None:
        return {"error": "claim not found"}
    result = dict(row)
    if not include_notes:
        result.pop("notes", None)
    return result

import sqlite3
from dataclasses import dataclass

import stripe
from langchain_core.tools import tool

_DB_PATH = "claims.db"


@dataclass
class VoidResult:
    payment_id: str
    refunded_cents: int
    refund_id: str
    deleted: bool
    message: str


@tool
def void_claim_payment(payment_id: str, reason: str) -> VoidResult:
    conn = sqlite3.connect(_DB_PATH)
    try:
        row = conn.execute(
            "SELECT stripe_charge_id, amount_cents, status FROM claim_payments WHERE payment_id = ?",
            (payment_id,),
        ).fetchone()
        if row is None:
            return VoidResult(payment_id, 0, "", False, "payment not found")
        charge_id, amount_cents, status = row
        if status != "pending":
            return VoidResult(payment_id, 0, "", False, f"payment is {status}, cannot void")
        refund = stripe.Refund.create(
            charge=charge_id,
            amount=amount_cents,
            metadata={"payment_id": payment_id, "reason": reason},
        )
        conn.execute("DELETE FROM claim_payments WHERE payment_id = ?", (payment_id,))
        conn.commit()
        return VoidResult(payment_id, amount_cents, refund.id, True, "payment voided")
    finally:
        conn.close()
